% mathsmap-diagram-colours {"version":1,"kind":"geometry","base":[],"semantic":[],"reference":"source page 73 p73-q10-alternative-c-diagram"}
\begin{tikzpicture}[x=9mm,y=9mm,every node/.style={font=\fontsize{10}{12}\selectfont},line join=round]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\coordinate (A) at (0,0);
\coordinate (B) at ({6*cos(15)},{-6*sin(15)});
\coordinate (C) at ({(3*sqrt(3)+sqrt(7))*cos(45)},{-(3*sqrt(3)+sqrt(7))*sin(45)});
\coordinate (D) at ({(3*sqrt(3)-sqrt(7))*cos(45)},{-(3*sqrt(3)-sqrt(7))*sin(45)});
\draw[black,line width=0.8pt] (A)--(B)--(C)--cycle (B)--(D);
\node[above left] at (A) {$A$};
\node[above right] at (B) {$B$};
\node[below right] at (C) {$C$};
\node[above right,xshift=1mm,yshift=1mm] at (D) {$C'$};
\path (A)--(B) node[midway,above] {$6$};
\path (B)--(C) node[midway,right,xshift=3mm] {$4$};
\foreach \P in {C,D} {
\coordinate (M) at ($(B)!0.5!(\P)$);
\draw[black,line width=0.4pt] ($(M)!1.5mm!90:(\P)$)--($(M)!1.5mm!-90:(\P)$);
\coordinate (N) at ($(B)!0.53!(\P)$);
\draw[black,line width=0.4pt] ($(N)!1.5mm!90:(\P)$)--($(N)!1.5mm!-90:(\P)$);
}
\draw[<->,black,line width=0.4pt] ($(A)+(-0.55,-0.55)$)--($(D)+(-0.55,-0.55)$) node[midway,sloped,below] {$3\sqrt3-\sqrt7$};
\draw[<->,black,line width=0.4pt] ($(A)+(-1.3,-1.3)$)--($(C)+(-1.3,-1.3)$) node[midway,sloped,below] {$3\sqrt3+\sqrt7$};
\end{tikzpicture}
